package com.enterprise.procurement.admin.controller;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.enterprise.procurement.admin.entity.OperationLogEntity; import com.enterprise.procurement.admin.mapper.OperationLogMapper; import com.enterprise.procurement.dto.ApiResponse; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/operation-logs") public class OperationLogController { private final OperationLogMapper mapper; public OperationLogController(OperationLogMapper m){mapper=m;} @GetMapping @PreAuthorize("hasRole('ADMIN')") public ApiResponse<?> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){Page<OperationLogEntity> p=mapper.selectPage(new Page<>(page,size),null);return ApiResponse.ok(java.util.Map.of("records",p.getRecords(),"total",p.getTotal(),"page",p.getCurrent(),"size",p.getSize()));} }
